import java.nio.file.*;import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.tree.*;
public class PatchMedical{static ClassNode read(Path p)throws Exception{ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(p)).accept(c,0);return c;}static void save(ClassNode c,Path p)throws Exception{ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);Files.write(p,w.toByteArray());}public static void main(String[] args)throws Exception{Path root=Path.of(args[0]);Path rules=root.resolve("dev/zomboid/firstaid/Rules.class");ClassNode c=read(rules);int changed=0;for(MethodNode m:c.methods)if(m.name.equals("speed"))for(AbstractInsnNode ins:m.instructions.toArray())if(ins instanceof LdcInsnNode l&&l.cst.equals(0.7d)){l.cst=0.25d;changed++;}if(changed!=1)throw new AssertionError();save(c,rules);
Path treat=root.resolve("ichttt/mods/firstaid/compat/lrtactical/TreatmentV33.class");c=read(treat);for(MethodNode m:c.methods)if(m.name.equals("applied"))for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==Opcodes.RETURN){InsnList i=new InsnList();i.add(new VarInsnNode(Opcodes.ALOAD,1));i.add(new VarInsnNode(Opcodes.ALOAD,3));i.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/firstaid/DressingBoost","applied","(Ljava/lang/Object;Ljava/lang/Object;)V",false));m.instructions.insertBefore(n,i);}save(c,treat);
Path client=root.resolve("ichttt/mods/firstaid/client/ClientEventHandler.class");c=read(client);for(MethodNode m:c.methods)if(m.name.equals("tooltipItems"))for(AbstractInsnNode n:m.instructions.toArray())if(n.getOpcode()==Opcodes.RETURN){InsnList i=new InsnList();i.add(new VarInsnNode(Opcodes.ALOAD,0));i.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/firstaid/DressingBoost","tooltip","(Ljava/lang/Object;)V",false));m.instructions.insertBefore(n,i);}save(c,client);
Path bridge=root.resolve("ichttt/mods/firstaid/compat/lrtactical/MedicalBridge.class");c=read(bridge);MethodNode m=c.methods.stream().filter(v->v.name.equals("medicalComplete")).findFirst().orElseThrow();InsnList i=new InsnList();i.add(new VarInsnNode(Opcodes.ALOAD,0));i.add(new VarInsnNode(Opcodes.ALOAD,1));i.add(new VarInsnNode(Opcodes.ALOAD,2));i.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/firstaid/DressingBoost","lrBandage","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Z",false));LabelNode original=new LabelNode();i.add(new JumpInsnNode(Opcodes.IFEQ,original));i.add(new InsnNode(Opcodes.ICONST_1));i.add(new InsnNode(Opcodes.IRETURN));i.add(original);i.add(new FrameNode(Opcodes.F_SAME,0,null,0,null));m.instructions.insert(i);save(c,bridge);Path clinical=root.resolve("ichttt/mods/firstaid/survival/ClinicalHooks.class");c=read(clinical);for(MethodNode v:c.methods)if(v.name.equals("applyInjuryEffect")||v.name.equals("addInjuryEffect")){int player=v.name.equals("applyInjuryEffect")?1:0,effect=player+1;InsnList hook=new InsnList();hook.add(new VarInsnNode(Opcodes.ALOAD,player));hook.add(new VarInsnNode(Opcodes.ALOAD,effect));hook.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/firstaid/DressingBoost","mildSlow","(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;",false));hook.add(new TypeInsnNode(Opcodes.CHECKCAST,"net/minecraft/world/effect/MobEffectInstance"));hook.add(new VarInsnNode(Opcodes.ASTORE,effect));v.instructions.insert(hook);}save(c,clinical);System.out.println("PASS mobility cap, completed dressing boost, differentiated tooltip and optional LR bandage bridge");}}
